    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        require(amount > 0);
        require(amount <= c.balanceOf(address(this)));

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(address(this));
            uint256 recipientAfter = c.balanceOf(recipient);

            if (address(this) != address(c) && recipient != address(c)) {
                assert(senderAfter + recipientAfter == senderBefore + recipientBefore);
            } else {
                assert(true);
            }
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

