contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(sender != recipient, "self transfer");
        require(amount > 0, "zero amount");
        require(amount > 0, "amount must be positive");

        // Ensure sender has enough tokens before attempting the transfer.
        require(c.balanceOf(sender) >= amount, "insufficient balance for test");

        // Capture the deterministic rewards parameters and the balances just before the transfer.
        uint256 minTxn = c.minTxnAmount();
        uint256 rRate = c.rewardRate();
        uint256 pct = c.percent();
        uint256 cBal = c.balanceOf(address(c));

        uint256 senderBefore = c.balanceOf(sender);
        uint256 recipientBefore = c.balanceOf(recipient);

        // The deciding call: a transfer from sender to recipient must be performed by sender.
        // The test contract is msg.sender for this call, so we must use transferFrom
        // after the sender approves the test contract.
        // Approving and transferring are state-changing calls, each a top-level statement.
        c.approve(sender, amount);
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderAfter = c.balanceOf(sender);
        uint256 recipientAfter = c.balanceOf(recipient);

        // The reward path adds tokens to the recipient (buy) or sender (sell)
        // when the transfer amount is at least minTxnAmount and the contract holds enough tokens.
        // That path makes the balances differ from the basic conservation equality.
        // A non-reward path satisfies: senderAfter + amount == senderBefore and
        // recipientAfter == recipientBefore + amount.  When the reward path triggers,
        // the recipient (or sender) gets an extra rewardAmount = amount * rewardRate / percent,
        // assuming the contract has enough balance for it.
        // We construct a single general rule that holds in all cases by making the
        // expected net recipient or sender increase match the observed one,
        // but only when the call did not revert.
        bool rewardTriggered = (amount >= minTxn) && (cBal >= amount * rRate / pct);
        uint256 rewardAmt = amount * rRate / pct;

        if (!reverted) {
            // Either a basic transfer occurred, or a reward path occurred.
            // Under a basic transfer, senderAfter == senderBefore - amount and
            // recipientAfter == recipientBefore + amount.
            // Under a reward path, the recipient receives amount plus rewardAmt (buy)
            // or the sender receives amount plus rewardAmt (sell) and the counterparty
            // still sees the basic transfer.  For our chosen sender/recipient pair,
            // we cannot know whether it is a buy or a sell because `_allowedRoles`
            // is not observable, but the balance changes are still rate-based.
            // The general invariant that always holds for the non-fee transfer path is:
            bool basic = (senderAfter + amount == senderBefore) &&
                         (recipientAfter == recipientBefore + amount);
            bool rewarded = rewardTriggered &&
                            ((recipientAfter == recipientBefore + amount + rewardAmt) ||
                             (senderAfter + amount == senderBefore + rewardAmt));
            assert(basic || rewarded);
        } else {
            // When the call reverts no state changes occurred.
            assert(senderAfter == senderBefore && recipientAfter == recipientBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
