            try c.setMinTxnAmount(newMinTxnAmount) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.minTxnAmount() == oldMinTxnAmount);
        } else if (selector % 4 == 2) {
            try c.setRewardRate(newRewardRate) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.rewardRate() == oldRewardRate);
        } else {
            try c.changeUniswapV2Pair(newPair) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.uniswapV2Pair() == oldPair);
        }
    }
}

