contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address buyer, address seller, uint256 minAmt) public {
        require(buyer != address(0) && seller != address(0), "zero addr");
        require(buyer != seller, "same addr");
        require(minAmt > 0, "zero min");
        require(minAmt == 10000 * 1e18, "not min amt");

        // ensure sender is an allowed role by having the owner transfer to it
        c.transfer(buyer, minAmt);

        // minTxnAmount is a public state variable with an auto-generated getter
        require(c.minTxnAmount() == minAmt, "minTxn mismatch");

        // rewardRate and percent are public state variables
        uint256 rate = c.rewardRate();
        uint256 pct = c.percent();

        uint256 balBefore = c.balanceOf(address(c));
        uint256 buyerRewardBefore = c.txReward(buyer);

        // deciding call: buyer (an allowed role) sends exactly minTxnAmount
        bool reverted;
        try c.transfer(seller, minAmt) { reverted = false; } catch { reverted = true; }

        if (!reverted && balBefore >= minAmt * rate / pct) {
            uint256 expectedReward = minAmt * rate / pct;
            assert(c.txReward(buyer) == buyerRewardBefore + expectedReward);
        } else {
            assert(c.txReward(buyer) == buyerRewardBefore);
        }
    }

    receive() external payable {}
}

