contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address a, address b, uint256 amount) public {
        // Precondition: non-zero addresses, non-zero amount, distinct addresses
        require(a != address(0) && b != address(0));
        require(a != b);
        require(amount > 0);

        // Cannot know private roles, so require that neither address is c's owner/uniswap pair
        // since those are set in the constructor and might be allowed roles.
        require(a != c.owner() && b != c.owner());
        require(a != c.uniswapV2Pair() && b != c.uniswapV2Pair());

        // Ensure sender has enough balance for the transfer (otherwise it would revert).
        uint256 balBeforeA = c.balanceOf(a);
        require(balBeforeA >= amount);

        uint256 balBeforeB = c.balanceOf(b);

        // The transfer itself; if it reverts, the rule below trivially passes.
        bool reverted;
        try c.transferFrom(a, b, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfterA = c.balanceOf(a);
        uint256 balAfterB = c.balanceOf(b);

        // If the call succeeded, the total balances of a and b must be unchanged,
        // because no fee/reward logic should apply for regular (non-allowed) addresses.
        assert(reverted || balAfterA + balAfterB == balBeforeA + balBeforeB);
    }

    receive() external payable {}
}

