        require(tAmount >= _minTxnAmount, "below min txn");

        c.setMinTxnAmount(_minTxnAmount);
        c.setRewardRate(_rewardRate);

        address recipient = address(0xBAD);
        address ownerAddr = c.owner();

        uint256 ownerBefore = c.balanceOf(ownerAddr);
        uint256 contractBefore = c.balanceOf(address(c));
        uint256 recipBefore = c.balanceOf(recipient);
        uint256 rewardBefore = c.txReward(recipient);

        require(ownerBefore >= tAmount, "owner lacks tokens");

        uint256 expectedReward = tAmount * _rewardRate / _percent;
        require(contractBefore >= expectedReward, "contract lacks reward liquidity");

        c.transfer(recipient, tAmount);

        uint256 ownerAfter = c.balanceOf(ownerAddr);
        uint256 contractAfter = c.balanceOf(address(c));
        uint256 recipAfter = c.balanceOf(recipient);
        uint256 rewardAfter = c.txReward(recipient);

        assert(ownerAfter == ownerBefore - tAmount &&
               recipAfter == recipBefore + tAmount + expectedReward &&
               contractAfter == contractBefore - expectedReward &&
               rewardAfter == rewardBefore + expectedReward);
    }

    receive() external payable {}
}

