    }

    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(amount > 0, "zero amount");

        c.changeOwner(sender);

        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 contractBalBefore = c.balanceOf(address(c));
        uint256 rewardBefore = c.txReward(recipient);

        require(senderBalBefore >= amount, "sender balance too low");

        c.transferFrom(sender, recipient, amount);

        uint256 recipientBalAfter = c.balanceOf(recipient);
        uint256 contractBalAfter = c.balanceOf(address(c));
        uint256 rewardAfter = c.txReward(recipient);

        uint256 rewardPaid = rewardAfter - rewardBefore;

        assert(recipientBalAfter == recipientBalBefore + amount + rewardPaid);
        assert(contractBalAfter == contractBalBefore - rewardPaid);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "zero recipient");
        require(recipient != address(this), "recipient is test contract");
        require(amount > 0, "zero amount");

        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipientBalBefore = c.balanceOf(recipient);

        require(senderBalBefore >= amount, "sender balance too low");

        c.transfer(recipient, amount);

        uint256 senderBalAfter = c.balanceOf(address(this));
        uint256 recipientBalAfter = c.balanceOf(recipient);

        assert(senderBalAfter == senderBalBefore - amount && recipientBalAfter - recipientBalBefore <= amount);
    }

    receive() external payable {}
}
